sys_script_include.script:
function AiToolGetBacklog(vBacklogItem)
{
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var Clone = x_snc_devtools.Clone;
	var GetArrayValue = x_snc_devtools.GetArrayValue;
	var GetRecord = x_snc_devtools.GetRecord;


	if (IsAgileAppInstalled() == true)
	{
		var grBacklogItem = x_snc_agile.GetBacklogItemRecord(vBacklogItem);
		if (IsValidRecord(grBacklogItem) == true)
		{
			var grBacklog = x_snc_agile.GetBacklogRecord(grBacklogItem.backlog);

			var backlog = Clone(grBacklog);
			backlog._components = [];

			if (IsValidRecord(grBacklog) == true)
			{

				var grComponentBacklog = new GlideRecord('x_snc_agile_m2m_components_backlogs');
				grComponentBacklog.addQuery('backlog',grBacklog.sys_id);
				grComponentBacklog.query();

				while (grComponentBacklog.next())
				{
					backlog._components.push(
						Clone(
							GetRecord('x_snc_agile_component',grComponentBacklog.component)));
				}


				return backlog;
			}
		}
	}
	return {};
}
